<template>
 <ThemePage><view class="people-page" data-promoter-people>
  <view class="people-header"><view class="search-pill"><text class="search-icon">⌕</text><input v-model="state.keyword" confirm-type="search" maxlength="128" placeholder="搜索用户名称" aria-label="搜索用户名称" @confirm="state.search"/><button class="search-button" @tap="state.search">搜索</button></view>
   <view v-if="state.showGrades" class="grade-tabs"><button class="grade-tab" :class="{selected:state.grade===0}" :aria-selected="state.grade===0" @tap="state.chooseGrade(0)">{{ state.divisionMode?'代理商':'一级' }}({{ state.total }})</button><button class="grade-tab" :class="{selected:state.grade===1}" :aria-selected="state.grade===1" @tap="state.chooseGrade(1)">{{ state.divisionMode?'员工':'二级' }}({{ state.totalLevel }})</button></view>
