   <view v-if="state.loading" class="people-state" role="status">推广人读取中…</view>
   <view v-if="state.error" class="people-state people-error" role="alert">{{ state.error }}</view>
   <view v-if="state.loaded && !state.loading && !state.error && !state.items.length" class="people-empty"><image src="/static/php-points/noOrder.gif" mode="aspectFit"/><view>暂无数据～</view></view>
   <button v-if="state.error" class="people-control" :disabled="state.loading" @tap="state.retry">重试当前页</button>
   <button v-if="state.hasMore && !state.error" class="people-control" :disabled="state.loading" @tap="state.load(true)">{{ state.loading?'读取中…':'加载更多' }}</button>
   <view v-if="state.loaded && state.items.length && !state.hasMore && !state.loading && !state.error" class="people-state">{{ state.page===500?'已显示前10000位推广人':'没有更多了～' }}</view>
   <view v-if="state.mediaExpired" class="people-state">头像已过期，请刷新推广人</view><button class="people-control" :disabled="state.loading" @tap="state.refresh">刷新推广人</button>
  </template>
 </view></ThemePage>
</template>
<script setup lang="ts">
